// SPDX-License-Identifier: GPL-2.0-or-later
// bbport: fixes to the game's own code (CUSA03173 1.09), from the SrShadowy fork
// (extra/core/engine_fixes; upstream bloodborne_pc 0.7), as native hook slots of the recompiled
// units (bbport_hook_sites.h; the catalog is tools/recomp/variants/hooks-patchers.txt, generated by
// running this together with the other patchers). Without a slot at a site (a libbbaot.so made by
// an older Rebuild Tool) the fix is not installed and the game runs as before.
//
// - Play time (0x19419de): the game truncates each frame's milliseconds: at 120 FPS (8.33 ms) a
//   frame counted 8 ms and the play time ran 4 % slow, more the higher the frame rate. The
//   fraction is carried to the next frame (one thread: the game's main loop).
// - Hit collector (0xb84ce0): a degenerate query (a zero-length ray while the world is paused)
//   filled Havok's collector without end until an allocation failed (SIGSEGV at 0xf00010). Past
//   BB_HIT_COLLECTOR_CAP (65536) hits the call writes into this thread's scratch array instead:
//   the game's function runs as it is, nothing is skipped.
// - Character id (0x1c43ee0): an invalid id (0x8000000000000000) in the player's data
//   (GameDataMan + 8 -> +0x690) is cleared before the save serializes it (corrupted saves).
// The fork's light grid hook is not taken over.
#include "bbport_engine_fixes.h"
#include "bbport_hook_sites.h"
#include "../../src/guest_cpu.h"

#include <sys/mman.h>

#include <array>
#include <atomic>
#include <cstdio>
#include <cstdlib>
#include <cstring>

namespace BbEngineFixes {
namespace {
using u64 = std::uint64_t;
using u8 = std::uint8_t;

u64 image_base = 0;
/// vcvttss2si rcx, xmm0: the frame's play time in ms (xmm0 = dt * 1000), added to the save's
/// play time (GameDataMan + 0x94) right after.
constexpr u64 PlayTimeConvert = 0x19419de;
constexpr std::array<u8, 5> PlayTimeConvertCode = {0xc4, 0xe1, 0xfa, 0x2c, 0xc8};
/// Havok's 96-byte hit collector push_back (rdi = the array, rsi = the hit).
constexpr u64 HitPushBack = 0xb84ce0;
constexpr std::array<u8, 6> HitPushBackEntry = {0x55, 0x48, 0x89, 0xe5, 0x41, 0x56};
/// The step before a save serializes the player's data.
constexpr u64 CharaStep = 0x1c43ee0;
constexpr std::array<u8, 6> CharaStepEntry = {0x55, 0x48, 0x89, 0xe5, 0x41, 0x57};
constexpr u64 GameDataMan = 0x553b130;

std::atomic<u64> hits_dropped{0}, chara_ids_cleared{0};

/// The play time's fraction goes to the next frame (xmm0's low float, ms: the instruction truncates it next).
std::uint32_t PlayTimeSlot(void*, GuestRegsEx* r) {
    static double carry_ms = 0.0;
    float ms = 0.0f;
    std::memcpy(&ms, r->ymm[0], sizeof(ms));
    const double total = double(ms) + carry_ms;
    if (!(total > 0.0) || total > 60000.0) {
        carry_ms = 0.0; // a pause or a hitch: as the game counted it
        return GUEST_HOOK_CONTINUE;
    }
    const double whole = double(std::uint64_t(total));
    carry_ms = total - whole;
    const float out = float(whole);
    std::memcpy(r->ymm[0], &out, sizeof(out));
    return GUEST_HOOK_CONTINUE;
}

struct alignas(16) ScratchArray {
    u8 head[0x20];
    void* data;
    std::int32_t size;
    std::int32_t capacity;
    u8 hit[96]; ///< the one hit the array holds
};
static_assert(sizeof(ScratchArray) == 0x90);

/// This thread's scratch array, in guest memory (a page below the image, like the other shims'
/// near mappings): the game's code reads and writes it, host thread-local memory is not where it
/// expects its data. One per thread for the thread's life; null when the pages are used up.
ScratchArray* ThreadScratch() {
    constexpr u64 Pages = 16, SlotsPerPage = 4096 / sizeof(ScratchArray);
    static u8* pool = [] {
        for (u64 k = 1; k <= 64; ++k) {
            const u64 hint = image_base - (192 + k * Pages) * (4ull << 20); // away from the other shims'
            void* p = mmap(reinterpret_cast<void*>(hint), Pages * 4096, PROT_READ | PROT_WRITE,
                           MAP_PRIVATE | MAP_ANONYMOUS | MAP_FIXED_NOREPLACE, -1, 0);
            if (p != MAP_FAILED) return static_cast<u8*>(p);
        }
        return static_cast<u8*>(nullptr);
    }();
    static std::atomic<u64> used{0};
    thread_local ScratchArray* mine = nullptr;
    if (!mine && pool) {
        const u64 slot = used.fetch_add(1, std::memory_order_relaxed);
        if (slot < Pages * SlotsPerPage) {
            mine = reinterpret_cast<ScratchArray*>(pool + slot / SlotsPerPage * 4096 +
                                                   slot % SlotsPerPage * sizeof(ScratchArray));
        }
    }
    return mine;
}
/// At the entry of the push_back: a full collector gets this thread's one-hit scratch array instead.
std::uint32_t HitPushBackSlot(void*, GuestRegsEx* r) {
    static const std::int32_t cap = [] {
        const char* env = std::getenv("BB_HIT_COLLECTOR_CAP");
        const long v = env ? std::strtol(env, nullptr, 10) : 65536;
        return std::int32_t(v > 0 ? v : 65536);
    }();
    const auto* array = reinterpret_cast<const u8*>(r->gpr[GUEST_RDI]);
    if (!array) return GUEST_HOOK_CONTINUE;
    std::int32_t size = 0;
    void* data = nullptr;
    std::memcpy(&size, array + 0x28, sizeof(size));
    std::memcpy(&data, array + 0x20, sizeof(data));
    if (size < cap && (data || size == 0)) return GUEST_HOOK_CONTINUE;
    ScratchArray* scratch = ThreadScratch();
    if (!scratch) return GUEST_HOOK_CONTINUE;
    scratch->data = scratch->hit;
    scratch->size = 0;
    scratch->capacity = 1;
    r->gpr[GUEST_RDI] = reinterpret_cast<u64>(scratch);
    if (hits_dropped.fetch_add(1, std::memory_order_relaxed) == 0) {
        std::printf("Engine fixes: a hit collector reached %d hits: further hits dropped\n", int(size));
    }
    return GUEST_HOOK_CONTINUE;
}

std::uint32_t CharaStepSlot(void*, GuestRegsEx*) {
    u64 manager = 0, player = 0, id = 0;
    std::memcpy(&manager, reinterpret_cast<const void*>(image_base + GameDataMan), sizeof(manager));
    if (manager < 0x100000000ull) return GUEST_HOOK_CONTINUE;
    std::memcpy(&player, reinterpret_cast<const void*>(manager + 0x8), sizeof(player));
    if (player < 0x100000000ull) return GUEST_HOOK_CONTINUE;
    auto* field = reinterpret_cast<u8*>(player + 0x690);
    std::memcpy(&id, field, sizeof(id));
    if (id == 0x8000000000000000ull) {
        const u64 none = 0;
        std::memcpy(field, &none, sizeof(none));
        if (chara_ids_cleared.fetch_add(1, std::memory_order_relaxed) == 0) {
            std::printf("Engine fixes: an invalid character id cleared before a save\n");
        }
    }
    return GUEST_HOOK_CONTINUE;
}

/// What one fix does at install, for the log line; `no_slot` counts the fixes that lacked a slot.
const char* Install(const char* env, u64 offset, const u8* code, std::size_t length, GuestHookEx fn, int& no_slot) {
    if (const char* v = std::getenv(env); v && v[0] == '0') return "off";
    if (std::memcmp(reinterpret_cast<const void*>(image_base + offset), code, length) != 0) return "not installed (other code there)";
    if (!BbHookSites::Available(image_base + offset)) {
        ++no_slot;
        return "inactive (no hook slot)";
    }
    return BbHookSites::Slot(image_base + offset, image_base, length, fn, nullptr) ? "on" : "not installed";
}
} // namespace

void PatchImage(unsigned char* image, std::uint64_t size) {
    image_base = reinterpret_cast<u64>(image);
    if (size < 0x5600000) return;
    int no_slot = 0;
    const char* play = Install("BB_FIX_PLAY_TIME", PlayTimeConvert, PlayTimeConvertCode.data(), PlayTimeConvertCode.size(), PlayTimeSlot, no_slot);
    const char* hits = Install("BB_FIX_HIT_COLLECTOR", HitPushBack, HitPushBackEntry.data(), HitPushBackEntry.size(), HitPushBackSlot, no_slot);
    const char* chara = Install("BB_FIX_CHARA_ID", CharaStep, CharaStepEntry.data(), CharaStepEntry.size(), CharaStepSlot, no_slot);
    std::printf("Engine fixes: high frame rate play time %s, hit collector cap %s, save character id guard %s%s\n", play, hits, chara,
                no_slot ? " (the libbbaot.so predates these hook sites: rebuild it with a newer Rebuild Tool)" : "");
}
} // namespace BbEngineFixes
